"""Hard synthetic files for the source catalog, generated by code at test time.

Two source roots stand for two collections (``phone_a`` and ``drive_b``). The
returned dict declares every planted case so tests assert against expectations
instead of re-deriving them. Contents are fictional; names use example domains.
"""
from __future__ import annotations

import gzip
import io
import os
import struct
import tarfile
import warnings
import zipfile
import zlib
from datetime import datetime, timezone
from pathlib import Path

PDF_SHARED = (b'%PDF-1.4\n% AGEDS synthetic shared report\n1 0 obj << /Type /Catalog >> endobj\n'
              b'trailer << /Root 1 0 R >>\n%%EOF\n')
PDF_DAT = (b'%PDF-1.7\n% AGEDS synthetic export attachment\n1 0 obj << /Type /Catalog >> endobj\n'
           b'trailer << /Root 1 0 R >>\n%%EOF\n')
DEFAULT_MTIME = datetime(2024, 1, 7, 12, 0, tzinfo=timezone.utc).timestamp()
CLUSTER1 = [datetime(2024, 1, d, 9, 0, tzinfo=timezone.utc).timestamp() for d in (5, 7, 9)]
CLUSTER2 = [datetime(2024, 9, d, 9, 0, tzinfo=timezone.utc).timestamp() for d in (1, 3, 5)]
DOS_TIME = (2023, 6, 1, 10, 0, 0)


def _png() -> bytes:
    def chunk(kind: bytes, data: bytes) -> bytes:
        return struct.pack('>I', len(data)) + kind + data + struct.pack('>I', zlib.crc32(kind + data))
    header = struct.pack('>IIBBBBB', 1, 1, 8, 2, 0, 0, 0)
    return b'\x89PNG\r\n\x1a\n' + chunk(b'IHDR', header) + chunk(b'IDAT', zlib.compress(b'\x00\xff\x00\x00')) + chunk(b'IEND', b'')


def _ftyp(major: bytes, compatible: list[bytes]) -> bytes:
    body = major + b'\x00\x00\x02\x00' + b''.join(compatible)
    ftyp = struct.pack('>I', 8 + len(body)) + b'ftyp' + body
    mdat = struct.pack('>I', 16) + b'mdat' + b'synthetic'[:8]
    return ftyp + mdat


def _wav() -> bytes:
    data = b'\x00\x00' * 800
    fmt = struct.pack('<HHIIHH', 1, 1, 8000, 16000, 2, 16)
    body = b'WAVE' + b'fmt ' + struct.pack('<I', 16) + fmt + b'data' + struct.pack('<I', len(data)) + data
    return b'RIFF' + struct.pack('<I', len(body)) + body


def _cfb(stream_name: str) -> bytes:
    """Minimal OLE compound file: FAT sector 0, directory sector 1."""
    free, end, fat_sect = 0xFFFFFFFF, 0xFFFFFFFE, 0xFFFFFFFD
    header = bytearray(512)
    header[0:8] = bytes.fromhex('d0cf11e0a1b11ae1')
    struct.pack_into('<HHHHH', header, 0x18, 0x3E, 3, 0xFFFE, 9, 6)
    struct.pack_into('<I', header, 0x2C, 1)          # FAT sectors
    struct.pack_into('<I', header, 0x30, 1)          # first directory sector
    struct.pack_into('<I', header, 0x38, 4096)       # mini stream cutoff
    struct.pack_into('<III', header, 0x3C, end, 0, end)
    difat = [0] + [free] * 108
    struct.pack_into('<109I', header, 0x4C, *difat)
    fat = [fat_sect, end] + [free] * 126
    fat_sector = struct.pack('<128I', *fat)

    def entry(name: str, kind: int) -> bytes:
        raw = bytearray(128)
        encoded = (name + '\x00').encode('utf-16-le')
        raw[:len(encoded)] = encoded
        struct.pack_into('<HBB', raw, 64, len(encoded), kind, 1)
        struct.pack_into('<III', raw, 68, free, free, 1 if kind == 5 else free)
        struct.pack_into('<IQ', raw, 116, end, 0)
        return bytes(raw)
    directory = entry('Root Entry', 5) + entry(stream_name, 2) + bytes(128) * 2
    return bytes(header) + fat_sector + directory


def _zip(members: list[tuple], *, compression=zipfile.ZIP_DEFLATED) -> bytes:
    """members: (name, data[, date_time])."""
    buffer = io.BytesIO()
    with warnings.catch_warnings():
        warnings.simplefilter('ignore')  # duplicate names are a planted case
        with zipfile.ZipFile(buffer, 'w', compression) as archive:
            for member in members:
                name, data = member[0], member[1]
                info = zipfile.ZipInfo(name, date_time=member[2] if len(member) > 2 else DOS_TIME)
                info.compress_type = compression
                archive.writestr(info, data)
    return buffer.getvalue()


def _replace_names(data: bytes, mapping: dict[bytes, bytes]) -> bytes:
    for placeholder, raw in mapping.items():
        assert len(placeholder) == len(raw) and data.count(placeholder) == 2
        data = data.replace(placeholder, raw)
    return data


def _encrypted_zip() -> bytes:
    data = bytearray(_zip([('secret.txt', b'cipher-text-placeholder'), ('plain.txt', b'visible')],
                          compression=zipfile.ZIP_STORED))
    local = data.find(b'PK\x03\x04')
    central = data.find(b'PK\x01\x02')
    struct.pack_into('<H', data, local + 6, struct.unpack_from('<H', data, local + 6)[0] | 1)
    struct.pack_into('<H', data, central + 8, struct.unpack_from('<H', data, central + 8)[0] | 1)
    return bytes(data)


def _crc_zip() -> bytes:
    data = bytearray(_zip([('flipped.txt', b'0123456789 synthetic stored member')], compression=zipfile.ZIP_STORED))
    position = data.find(b'0123456789')
    data[position] ^= 0x01
    return bytes(data)


def _tar(members: list[tuple], mode: str) -> bytes:
    buffer = io.BytesIO()
    with tarfile.open(fileobj=buffer, mode=mode) as archive:
        for name, data, mtime in members:
            info = tarfile.TarInfo(name)
            if isinstance(data, str):  # symlink target
                info.type, info.linkname = tarfile.SYMTYPE, data
            else:
                info.size = len(data)
            info.mtime = mtime
            archive.addfile(info, None if isinstance(data, str) else io.BytesIO(data))
    return buffer.getvalue()


def _write(path: Path, data: bytes, mtime: float = DEFAULT_MTIME):
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(data)
    os.utime(path, (mtime, mtime))


def build(root: Path) -> dict:
    a = root / 'phone_a'
    b = root / 'drive_b'
    outside = root / 'outside_target'
    outside.mkdir(parents=True, exist_ok=True)
    (outside / 'private-looking.txt').write_bytes(b'must never be catalogued through a symlink')

    # --- shared content in three places across two collections
    _write(a / 'docs' / 'report.pdf', PDF_SHARED)
    level3 = _zip([('deep.txt', b'three zip levels down')])
    level2 = _zip([('level3.zip', level3)])
    level1 = _zip([('level2.zip', level2), ('copy-note.txt', b'level one note')])
    takeout = _zip([('Takeout/Drive/report.pdf', PDF_SHARED), ('Takeout/level1.zip', level1),
                    ('Takeout/Mail/readme.txt', b'synthetic takeout readme')])
    _write(a / 'archives' / 'takeout.zip', takeout)
    nested = _zip([('report.pdf', PDF_SHARED)])
    _write(b / 'backup.zip', _zip([('inner/nested.zip', nested), ('inner/notes.txt', b'drive notes')]))

    # --- signature over extension
    _write(a / 'export' / 'file-0001.dat', PDF_DAT)
    _write(a / 'photos' / 'IMG_0001.jpg', _png())
    _write(a / 'audio' / 'voice-note.m4a', _ftyp(b'isom', [b'isom', b'iso2', b'mp41']))
    _write(a / 'audio' / 'real.m4a', _ftyp(b'M4A ', [b'M4A ', b'isom']))
    _write(a / 'audio' / 'rec.wav', _wav())
    _write(a / 'audio' / 'clip.mp3', b'ID3\x04\x00\x00\x00\x00\x00\x00' + b'\xff\xfb\x90\x64' + b'\x00' * 400)
    _write(a / 'audio' / 'note.opus', b'OggS\x00\x02' + b'\x00' * 22 + b'OpusHead\x01\x01' + b'\x00' * 30)
    _write(a / 'audio' / 'memo.amr', b'#!AMR\n' + b'\x3c' * 64)
    _write(a / 'audio' / 'track.flac', b'fLaC\x00\x00\x00\x22' + b'\x00' * 40)
    _write(a / 'video' / 'clip.webm', b'\x1a\x45\xdf\xa3\x9f\x42\x86\x81\x01\x42\x82\x84webm' + b'\x00' * 32)
    _write(a / 'video' / 'clip.3gp', _ftyp(b'3gp4', [b'3gp4', b'isom']))
    _write(a / 'images' / 'pic.gif', b'GIF89a\x01\x00\x01\x00' + b'\x00' * 20)
    _write(a / 'images' / 'pic.webp', b'RIFF\x1a\x00\x00\x00WEBPVP8 ' + b'\x00' * 18)
    _write(a / 'images' / 'pic.heic', _ftyp(b'heic', [b'mif1', b'heic']))
    _write(a / 'docs' / 'letter.docx', _zip([('[Content_Types].xml', b'<Types/>'), ('word/document.xml', b'<w:document/>')]))
    _write(a / 'docs' / 'sheet.xlsx', _zip([('[Content_Types].xml', b'<Types/>'), ('xl/workbook.xml', b'<workbook/>')]))
    odt = io.BytesIO()
    with zipfile.ZipFile(odt, 'w') as archive:
        archive.writestr(zipfile.ZipInfo('mimetype', DOS_TIME), b'application/vnd.oasis.opendocument.text')
        archive.writestr(zipfile.ZipInfo('content.xml', DOS_TIME), b'<office:document-content/>', zipfile.ZIP_DEFLATED)
    _write(a / 'docs' / 'note.odt', odt.getvalue())
    _write(a / 'docs' / 'legacy.doc', _cfb('Workbook'))
    _write(a / 'mail' / 'archive.mbox', b'From alice@example.org Mon Jan  1 00:00:00 2024\nFrom: alice@example.org\n'
           b'To: bob@example.net\nSubject: synthetic\n\nbody\n')
    _write(a / 'mail' / 'message.eml', b'Received: from mx.example.org\nFrom: carol@example.com\nTo: dave@example.org\n'
           b'Subject: synthetic\nDate: Mon, 1 Jan 2024 10:00:00 +0100\nMessage-ID: <1@example.org>\n\nbody\n')
    _write(a / 'mail' / 'contacts.vcf', b'BEGIN:VCARD\r\nVERSION:3.0\r\nFN:Example Person\r\nEND:VCARD\r\n')
    _write(a / 'mail' / 'calendar.ics', b'BEGIN:VCALENDAR\r\nVERSION:2.0\r\nEND:VCALENDAR\r\n')
    _write(a / 'data' / 'bom.json', b'\xef\xbb\xbf \n  {"conversations": [], "source": "example.org"}\n')
    _write(a / 'data' / 'table.csv', b'date,number,duration\n2024-01-01,+48000000001,10\n2024-01-02,+48000000002,20\n')
    _write(a / 'data' / 'table.tsv', b'date\tnumber\n2024-01-01\t+31600000001\n')
    _write(a / 'data' / 'page.html', b'<!DOCTYPE html><html><body><script>alert(1)</script></body></html>')
    _write(a / 'data' / 'feed.xml', b'<?xml version="1.0"?><smses count="0"></smses>')

    # --- archives: tar.gz with a zip inside, tar.xz, tar.bz2, single gzip, optional formats
    inner = _zip([('inside.txt', b'zip inside a tarball')])
    tar_time = int(datetime(2023, 3, 1, 8, 0, tzinfo=timezone.utc).timestamp())
    _write(a / 'archives' / 'bundle.tar.gz', _tar([('bundle/readme.txt', b'tar readme', tar_time),
                                                   ('bundle/inner.zip', inner, tar_time),
                                                   ('bundle/link', '../../etc/passwd', tar_time)], 'w:gz'))
    _write(a / 'archives' / 'logs.tar.xz', _tar([('logs/a.log', b'xz member', tar_time)], 'w:xz'))
    _write(a / 'archives' / 'logs.tar.bz2', _tar([('logs/b.log', b'bz2 member', tar_time)], 'w:bz2'))
    gz = io.BytesIO()
    with gzip.GzipFile(filename='app.log', mode='wb', fileobj=gz, mtime=tar_time) as handle:
        handle.write(b'single gzip stream member\n')
    _write(a / 'logs' / 'app.log.gz', gz.getvalue())
    _write(a / 'archives' / 'sample.7z', b'7z\xbc\xaf\x27\x1c\x00\x04' + b'\x00' * 24)
    _write(a / 'archives' / 'sample.rar', b'Rar!\x1a\x07\x01\x00' + b'\x00' * 24)

    # --- adversarial member names
    evil = _zip([
        ('../evil.txt', b'parent traversal name'),
        ('/abs/path.txt', b'absolute name'),
        ('dir\\back\\slash.txt', b'backslash name'),
        ('dup.txt', b'first duplicate'),
        ('dup.txt', b'second duplicate'),
        ('cafX.txt', b'cp437 name'),
        ('zaXXXXXXXX.txt', b'unflagged utf-8 name'),
        ('flagged-ünï.txt', b'flagged utf-8 name'),
        ('odd!/name.txt', b'bang slash in name'),
        ('100%.txt', b'percent in name'),
        ('tab\tname.txt', b'control character in name'),
    ])
    evil = _replace_names(evil, {b'cafX.txt': b'caf\x82.txt', b'zaXXXXXXXX.txt': 'zażółć.txt'.encode()})
    _write(a / 'archives' / 'evil.zip', evil)
    _write(a / 'archives' / 'locked.zip', _encrypted_zip())
    whole = _zip([('first.txt', b'A' * 300), ('second.txt', b'B' * 300), ('third.txt', b'C' * 300)],
                 compression=zipfile.ZIP_STORED)
    _write(a / 'archives' / 'truncated.zip', whole[:len(whole) * 55 // 100])
    _write(a / 'archives' / 'crc.zip', _crc_zip())
    _write(a / 'archives' / 'bomb.zip', _zip([('zeros.bin', b'\x00' * (4 * 1024 * 1024))]))

    # --- empty files, collisions, odd disk names
    _write(a / 'empty' / 'empty.txt', b'')
    _write(a / 'empty' / 'empty.log', b'')
    _write(a / 'notes' / 'todo.txt', b'phone todo list')
    _write(b / 'todo.txt', b'drive todo list - different bytes')
    _write(a / 'a' / 'same-name.txt', b'variant one')
    _write(a / 'b' / 'same-name.txt', b'variant two')
    _write(a / 'misc' / '<script>alert(1).txt', b'html-looking name')
    bad_name = os.fsdecode(b'bad\xffname.txt')
    _write(a / 'misc' / bad_name, b'non utf-8 file name')

    # --- two clusters of filesystem times with a long gap
    for index, moment in enumerate(CLUSTER1, 1):
        _write(a / 'timeline' / 'cluster1' / f'day{index}.txt', f'cluster one {index}'.encode(), moment)
    for index, moment in enumerate(CLUSTER2, 1):
        _write(a / 'timeline' / 'cluster2' / f'day{index}.txt', f'cluster two {index}'.encode(), moment)

    # --- symlinks: inside, loop, outside (never followed)
    os.symlink('docs', a / 'link-to-docs')
    os.symlink('.', a / 'loop')
    os.symlink(str(outside), a / 'outside-link')

    return {
        'roots': {'phone_a': str(a), 'drive_b': str(b)},
        'outside_target': str(outside),
        'shared_pdf': {
            'sha256': __import__('hashlib').sha256(PDF_SHARED).hexdigest(),
            'locations': [('phone_a', 'docs/report.pdf', 0), ('phone_a', 'archives/takeout.zip!/Takeout/Drive/report.pdf', 1),
                          ('drive_b', 'backup.zip!/inner/nested.zip!/report.pdf', 2)],
        },
        'type_conflicts': {
            'export/file-0001.dat': ('pdf', 'opaque_extension'),
            'photos/IMG_0001.jpg': ('png', 'mismatch'),
            'audio/voice-note.m4a': ('mp4', 'variant'),
            'docs/legacy.doc': ('xls', 'variant'),
        },
        'type_matches': {
            'audio/real.m4a': 'm4a', 'audio/rec.wav': 'wav', 'audio/clip.mp3': 'mp3', 'audio/note.opus': 'opus',
            'audio/memo.amr': 'amr', 'audio/track.flac': 'flac', 'video/clip.webm': 'webm', 'video/clip.3gp': '3gp',
            'images/pic.gif': 'gif', 'images/pic.webp': 'webp', 'images/pic.heic': 'heic', 'docs/report.pdf': 'pdf',
            'docs/letter.docx': 'docx', 'docs/sheet.xlsx': 'xlsx', 'docs/note.odt': 'odt',
            'mail/archive.mbox': 'mbox', 'mail/message.eml': 'eml', 'mail/contacts.vcf': 'vcf',
            'mail/calendar.ics': 'ics', 'data/bom.json': 'json', 'data/table.csv': 'csv', 'data/table.tsv': 'tsv',
            'data/page.html': 'html', 'data/feed.xml': 'xml', 'archives/takeout.zip': 'zip',
            'archives/bundle.tar.gz': 'tar.gz', 'archives/logs.tar.xz': 'tar.xz', 'archives/logs.tar.bz2': 'tar.bz2',
            'logs/app.log.gz': 'gz', 'archives/sample.7z': '7z', 'archives/sample.rar': 'rar',
        },
        'zip_depth3': 'archives/takeout.zip!/Takeout/level1.zip!/level2.zip!/level3.zip!/deep.txt',
        'tar_zip_member': 'archives/bundle.tar.gz!/bundle/inner.zip!/inside.txt',
        'tar_symlink_member': 'archives/bundle.tar.gz!/bundle/link',
        'gzip_member': 'logs/app.log.gz!/app.log',
        'xz_member': 'archives/logs.tar.xz!/logs/a.log',
        'bz2_member': 'archives/logs.tar.bz2!/logs/b.log',
        'tar_mtime_utc': '2023-03-01T08:00:00Z',
        'zip_dos_local': '2023-06-01T10:00:00',
        'evil_members': {
            'archives/evil.zip!/../evil.txt': ['parent_traversal'],
            'archives/evil.zip!//abs/path.txt': ['absolute'],
            'archives/evil.zip!/dir\\back\\slash.txt': ['backslash'],
            'archives/evil.zip!/dup.txt': [],
            'archives/evil.zip!/dup.txt!2': ['duplicate_name_in_archive'],
            'archives/evil.zip!/caf%82.txt': ['non_utf8', 'cp437_or_unflagged_utf8'],
            'archives/evil.zip!/zażółć.txt': ['cp437_or_unflagged_utf8'],
            'archives/evil.zip!/flagged-ünï.txt': [],
            'archives/evil.zip!/odd%21/name.txt': [],
            'archives/evil.zip!/100%25.txt': [],
            'archives/evil.zip!/tab%09name.txt': ['control_chars'],
        },
        'cp437_display': 'café.txt',
        'unflagged_utf8_display': 'zażółć.txt',
        'encrypted_member': 'archives/locked.zip!/secret.txt',
        'truncated_zip': 'archives/truncated.zip',
        'crc_member': 'archives/crc.zip!/flipped.txt',
        'bomb_member': 'archives/bomb.zip!/zeros.bin',
        'adapter_unavailable': ['archives/sample.7z', 'archives/sample.rar'],
        'empty_files': ['empty/empty.txt', 'empty/empty.log'],
        'collision_names': {'todo.txt': 2, 'same-name.txt': 2},
        'symlinks': ['link-to-docs', 'loop', 'outside-link'],
        'non_utf8_disk_name': 'misc/bad%FFname.txt',
        'xss_name': '<script>alert(1).txt',
        'gap': {'collection': 'phone_a', 'type': 'txt', 'source': 'filesystem_stat',
                'last_before': '2024-01-09', 'first_after': '2024-09-01', 'min_days': 200},
    }
